<?php $ret = (float) $b['cnss'] + (float) $b['tax'] + (float) $b['advance'] + (float) $b['other_deduction']; $row = fn (string $l, mixed $gain, mixed $ded = null) => '<tr><td>' . e(t($l)) . '</td><td class="num">' . ($gain !== null ? money($gain, false) : '') . '</td><td class="num">' . ($ded !== null ? money($ded, false) : '') . '</td></tr>'; ?>
<link rel="stylesheet" href="<?= e(asset('addons/grh/grh.css')) ?>">
<div class="sheet grh-doc">
  <div class="head"><?php if ($logo = setting('company_logo')): ?><img src="<?= e(upload_url($logo)) ?>" alt="" style="max-height:55px"><br><?php endif; ?><b style="font-size:17px"><?= e(setting('company_name')) ?></b><br><?= e(setting('company_address')) ?><?= setting('company_nif') ? ' · NIF : ' . e(setting('company_nif')) : '' ?></div>
  <h2><?= e(t('BULLETIN DE PAIE')) ?></h2><div style="text-align:center"><?= e(t('Période :')) ?> <b><?= e($b['period']) ?></b><?= $b['status'] === 'brouillon' ? ' — <b>' . e(t('PROJET (paie non validée)')) . '</b>' : '' ?></div>
  <table class="kv"><tr><td><?= e(t('Employé')) ?></td><td><?= e($b['civility']) ?> <?= e($b['first_name']) ?> <?= e(mb_strtoupper($b['last_name'])) ?></td></tr><tr><td><?= e(t('Matricule')) ?></td><td><?= e($b['matricule']) ?></td></tr>
    <tr><td><?= e(t('Poste')) ?></td><td><?= e($b['poste']) ?><?= $b['grade'] ? ' (' . e($b['grade']) . ')' : '' ?><?= $b['departement'] ? ' — ' . e($b['departement']) : '' ?></td></tr><tr><td><?= e(t('Date d\'embauche')) ?></td><td><?= e(fdate($b['hire_date'], false)) ?></td></tr><tr><td><?= e(t('N° CNSS')) ?></td><td><?= e($b['cnss_number'] ?: '—') ?></td></tr></table>
  <table><thead><tr><th><?= e(t('Rubrique')) ?></th><th class="num"><?= e(t('Gains')) ?></th><th class="num"><?= e(t('Retenues')) ?></th></tr></thead><tbody>
    <?= $row('Salaire de base', $b['base']) ?><?= (float) $b['allowances'] > 0 ? $row('Primes et indemnités fixes', $b['allowances']) : '' ?><?= (float) $b['bonus'] > 0 ? $row('Prime exceptionnelle', $b['bonus']) : '' ?><?= (float) $b['overtime'] > 0 ? $row('Heures supplémentaires', $b['overtime']) : '' ?>
    <?= (float) $b['absence_deduction'] > 0 ? '<tr><td>' . e(t('Absences non payées')) . ' (' . e(qty($b['absence_days'])) . ' ' . e(t('jour(s)')) . ')</td><td></td><td class="num">' . money($b['absence_deduction'], false) . '</td></tr>' : '' ?>
    <tr style="font-weight:700;background:#f5f5f5"><td><?= e(t('SALAIRE BRUT')) ?></td><td class="num"><?= money($b['gross'], false) ?></td><td></td></tr>
    <?= $row('Cotisation sociale (part salariale)', null, $b['cnss']) ?><?= (float) $b['tax'] > 0 ? $row('Impôt sur salaire', null, $b['tax']) : '' ?><?= (float) $b['advance'] > 0 ? $row('Remboursement d\'avance', null, $b['advance']) : '' ?><?= (float) $b['other_deduction'] > 0 ? $row('Autres retenues', null, $b['other_deduction']) : '' ?>
    <tr style="font-weight:700;background:#f5f5f5"><td><?= e(t('TOTAL DES RETENUES')) ?></td><td></td><td class="num"><?= money($ret, false) ?></td></tr></tbody></table>
  <div class="net"><span><?= e(t('NET À PAYER')) ?></span><span><?= money($b['net']) ?></span></div><div style="text-align:center;font-style:italic"><?= e(amount_words((float) $b['net'])) ?> <?= e(currency()['name'] ?? '') ?></div>
  <table class="kv" style="margin-top:10px"><tr><td><?= e(t('Charges patronales')) ?></td><td class="num"><?= money($b['employer_charges']) ?></td></tr><tr><td><?= e(t('Paiement')) ?></td><td><?= e($b['bank_account'] ?: t('Espèces')) ?></td></tr><?php if ($b['note']): ?><tr><td><?= e(t('Note')) ?></td><td><?= e($b['note']) ?></td></tr><?php endif; ?></table>
  <div class="sign"><div><?= e(t('L\'employeur')) ?></div><div><?= e(t('L\'employé(e) (reçu le net à payer)')) ?></div></div>
  <p style="font-size:11px;color:#444;margin-top:14px"><?= e(t('Bulletin à conserver sans limitation de durée.')) ?></p>
</div>
